def transform(grid):
    g=[list(row) for row in grid]
    h,w=len(g),len(g[0])
    # Estimate the diagonal color cycle from the most regular interior cells.
    best=None
    for p in range(2,10):
        groups=defaultdict(Counter)
        total=0
        for r in range(3,h):
            for c in range(3,w):
                v=g[r][c]
                if v:
                    groups[(r+c)%p][v]+=1
                    total+=1
        agree=sum(max(cnt.values()) for cnt in groups.values())
        # A small complexity cost favors the shortest cycle that explains the data.
        score=(total-agree)/max(1,total)+0.002*p
        if best is None or score<best[0]:
            best=(score,p,groups)
    _,p,groups=best
    palette={k:cnt.most_common(1)[0][0] for k,cnt in groups.items()}
    out=[row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=0: continue
            if r<2 or c<2:
                out[r][c]=1
            elif r==2 or c==2:
                out[r][c]=4
            else:
                out[r][c]=palette.get((r+c)%p,1)
